#include <stdio.h>
#include <string.h>

int main(void) {
    char a[] = "{word}";
    char b[] = "{word}";

    if (strcmp(a, b) == 0) {
        printf("C 说它们一样喵\n");
    } else {
        printf("长得一模一样，C 却说它们不一样喵\n");
    }
    return 0;
